const hotFiles = ['auth.js', 'router.js', 'db.js', 'utils.js', 'api.js', 'types.js'];

function pickFile(rand, files) {
  return files[Math.floor(rand() * files.length)];
}

function simulateTrunkBased(rand, days) {
  let conflictedMerges = 0;
  for (let d = 0; d < days; d++) {
    const trunkFile = pickFile(rand, hotFiles);
    const branchFile = pickFile(rand, hotFiles);
    if (trunkFile === branchFile) conflictedMerges++;
  }
  return conflictedMerges;
}

