items.solution:
const hotFiles = ['auth.js', 'router.js', 'db.js', 'utils.js', 'api.js', 'types.js'];

function pickFile(rand, files) {
  return files[Math.floor(rand() * files.length)];
}

function simulateGitflow(rand, days) {
  const trunkTouches = new Set();
  const branchTouches = new Set();
  for (let d = 0; d < days; d++) {
    trunkTouches.add(pickFile(rand, hotFiles));
    branchTouches.add(pickFile(rand, hotFiles));
  }
  let conflictedFiles = 0;
  for (const f of branchTouches) {
    if (trunkTouches.has(f)) conflictedFiles++;
  }
  return conflictedFiles;
}

